import{z as l,x as o,o as B,c as C,q as A,j as r,D as a,d as e,s as i,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"融券与转融通","description":"","frontmatter":{"title":"融券与转融通","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-margin-lending-structure.md","filePath":"quant/cn-margin-lending-structure.md","lastUpdated":1791413859000}'),d={name:"quant/cn-margin-lending-structure.md"};function p(u,E,c,F,D,m){const n=o("Mermaid");return B(),C("div",null,[E[2]||(E[2]=A('<h1 id="融券与转融通" tabindex="-1">融券与转融通 <a class="header-anchor" href="#融券与转融通" aria-label="Permalink to &quot;融券与转融通&quot;">​</a></h1><div class="epigraph"><p>券源不是一条数据接口，是一个政策敏感的批发市场：零售端拿到的永远是余量，而批发的阀门握在公告手里。</p><footer>—— 据《转融通业务监督管理试行办法》与券商融券业务口径整理</footer></div><p><a href="/quant/cn-stockindex-basis">上一课</a>把股指期货读成贴水状态变量，空头腿的第一种工具立住了。个股空头是第二条工具线：<a href="/quant/cn-securities-lending">融券与转融通</a>已把转融通管道与 2024 年暂停写成按公告切换的状态变量，<a href="/quant/cn-short-constraint">融券与做空约束</a>已写标的与提价规则。本课深钻实践层：券源工程——可借清单从哪来、费率右尾怎么读、召回来了怎么办。后课默认你已经在跑一条合规通道。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>制度课留下的缺口在执行端。回测里的空头腿是一条数列；实盘里它是一份每天在变的券池：哪些券今天可借、借多少、什么费率、什么期限、何时可能被召回，都要在开盘前拿到。用公开的两融余额当自己的券池，等于把全国存量当成个人可借额度——余量早被别人占用。缺口是把券源做成有台账、有状态、有替代路径的工程，而不是回测脚本里的一列负权重。</p><p><span class="marginnote">直觉类比：回测里的空头腿像一张「无限借书卡」，实盘里的券池更像图书馆——你想借的那本只剩 3 本、还被别人预约着，逾期（召回）还得马上还。把全国馆藏当成自己的可借额度，是空头回测最常见的一厢情愿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>券池台账。每日快照记四列：标的、可借数量、费率、期限与召回条款；台账必须是时点的——今天借不到不等于上周借不到，反之亦然。借入决策按净口径：预期空头收益减融券费率与占用成本，再对召回概率打折；费率看分布右尾不读均值，特殊券与政策日的费率可以吞掉整个空头溢价。召回管理：召回通知到达后要强制买券还券，冲击自己承担，所以空头持仓集中度要预留召回冲击的余量，到期与展期提前安排。替代路径排序：融券借不到，先比股指期货空头的贴水成本与券息孰低（上一课的读数工程在这里变现），再决定降仓或改中性结构；<a href="/quant/cn-margin-short-t0">融券 T+0 封堵</a>堵住的日内空回转不在替代集里。</p>',8)),(B(),r(s,null,{default:a(()=>[i(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEMAND%5B%22%E7%A9%BA%E5%A4%B4%E9%9C%80%E6%B1%82%22%5D%20--%3E%20CHECK%7B%22%E5%88%B8%E6%B1%A0%E6%9C%89%E8%B4%A7%3F%22%7D%0A%20%20CHECK%20--%3E%7C%22%E6%98%AF%22%7C%20BORROW%5B%22%E8%9E%8D%E5%88%B8%EF%BC%9A%E8%B4%B9%E7%8E%87%E5%8F%B3%E5%B0%BE%2B%E5%8F%AC%E5%9B%9E%E6%8A%98%E4%BB%B7%22%5D%0A%20%20CHECK%20--%3E%7C%22%E5%90%A6%22%7C%20CMP%7B%22%E5%88%B8%E6%81%AF%20vs%20%E8%B4%B4%E6%B0%B4%E5%AD%B0%E4%BD%8E%3F%22%7D%0A%20%20CMP%20--%3E%7C%22%E5%88%B8%E6%81%AF%E4%BD%8E%22%7C%20WAIT%5B%22%E6%8C%82%E5%8F%B0%E8%B4%A6%E7%AD%89%E5%88%B8%E6%BA%90%E5%9B%9E%E8%A1%A5%22%5D%0A%20%20CMP%20--%3E%7C%22%E8%B4%B4%E6%B0%B4%E4%BD%8E%22%7C%20FUT%5B%22%E8%82%A1%E6%8C%87%E6%9C%9F%E8%B4%A7%E7%A9%BA%E5%A4%B4%E8%BF%9B%E7%BB%84%E5%90%88%22%5D%0A%20%20BORROW%20--%3E%20POS%5B%22%E7%A9%BA%E5%A4%B4%E6%8C%81%E4%BB%93%2B%E5%8F%AC%E5%9B%9E%E4%BD%99%E9%87%8F%22%5D%0A%20%20POS%20--%3E%20RECALL%7B%22%E5%8F%AC%E5%9B%9E%E9%80%9A%E7%9F%A5%3F%22%7D%0A%20%20RECALL%20--%3E%7C%22%E6%98%AF%22%7C%20BUYIN%5B%22%E5%BC%BA%E5%88%B6%E4%B9%B0%E5%88%B8%E8%BF%98%E5%88%B8%EF%BC%9A%E8%87%AA%E6%8B%85%E5%86%B2%E5%87%BB%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"券源为什么贵且不稳。供给端是持有人：公募、保险与战略配售股东出借，券才进入市场，出借受产品合同、比例与监管窗口约束，政策一收，供给整层关闭；需求端是所有中性、多空与套利策略共用的一个池子，稀缺定价把费率推到右尾。两端都随政策跳变，零售端只能拿到余量。这决定两件事：空头策略的容量上限写在券池里而不是成交额里；券息与贴水是同一枚硬币的两面——券源收紧，对冲需求挤入期货，贴水加深，两条空头工具共用一个价格（上一课的机制在此闭环）。",-1)),(B(),r(s,null,{default:a(()=>[i(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20OWN%5B%22%E6%8C%81%E6%9C%89%E4%BA%BA%EF%BC%9A%E5%85%AC%E5%8B%9F%20%2F%20%E4%BF%9D%E9%99%A9%20%2F%20%E6%88%98%E9%85%8D%E8%82%A1%E4%B8%9C%22%5D%20--%3E%7C%22%E5%87%BA%E5%80%9F%E8%B5%9A%E8%B4%B9%E7%8E%87%22%7C%20SS%5B%22%E8%AF%81%E9%87%91%E5%85%AC%E5%8F%B8%EF%BC%9A%E8%BD%AC%E8%9E%8D%E9%80%9A%E6%89%B9%E5%8F%91%E5%B9%B3%E5%8F%B0%22%5D%0A%20%20SS%20--%3E%7C%22%E8%BD%AC%E8%9E%8D%E5%88%B8%22%7C%20BROKER%5B%22%E8%AF%81%E5%88%B8%E5%85%AC%E5%8F%B8%E5%88%B8%E6%B1%A0%22%5D%0A%20%20BROKER%20--%3E%7C%22%E8%9E%8D%E5%88%B8%EF%BC%9A%E8%B4%B9%E7%8E%87%20%2B%20%E4%BF%9D%E8%AF%81%E9%87%91%22%7C%20INV%5B%22%E6%8A%95%E8%B5%84%E8%80%85%E7%A9%BA%E5%A4%B4%22%5D%0A%20%20POLICY%5B%22%E7%9B%91%E7%AE%A1%E7%AA%97%E5%8F%A3%20%2F%20%E6%9A%82%E5%81%9C%E5%85%AC%E5%91%8A%22%5D%20--%3E%7C%22%E6%95%B4%E5%B1%82%E5%85%B3%E9%97%AD%E4%BE%9B%E7%BB%99%22%7C%20SS%0A%20%20INV%20--%3E%7C%22%E5%8F%AC%E5%9B%9E%E6%97%B6%E5%BC%BA%E5%88%B6%E4%B9%B0%E5%88%B8%E8%BF%98%E5%88%B8%22%7C%20BROKER%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">出借端同样有账可算：持有底仓的账户把券出借可以赚一笔出借费，代价是出借期间的投票权与召回限制；把「出借增强」写进产品预期收益时，它是政策情景的函数，不能按常数外推。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写灰色券源与规避暂停的安排；港股通与 A 股融券的标的、费率规则不可混用；收益互换等场外空头工具的杠杆与合规另论。可融名单与实时费率以券商柜台与当期公告为准。</p><p><span class="marginnote">术语翻译：「转融通」就是券的批发中转——持有人把券借给证金公司（批发商），券商再从证金批发、零售给做空的投资者。所以政策收紧批发阀门（如 2024 年暂停转融券）时，零售端即使什么都没做错，券源也会整层消失。</span></p><p><span class="marginnote">数字实例：融券费率年化 10% 的券，做空一年的预期超额只有 8% 时，光券息就倒亏 2 个百分点；而特殊券在政策日的费率可以跳到年化 18% 以上——这就是为什么台账要读费率分布的右尾，而不是读均值。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>券池台账按日快照、按时点记录可借量、费率与召回条款。</li><li>费率读右尾不读均值；公开余量不是你的可借额度。</li><li>召回是空头腿的隐形尾部风险，集中度要预留买券还券的冲击余量。</li><li>券息与贴水联动：券源收紧把对冲需求挤进期货，两条空头工具一条价格。</li><li>出处：转融通试行办法与证监会 2024 年公开说明口径；制度细节见<a href="/quant/cn-securities-lending">融券与转融通</a>。</li></ul>',7))])}const _=l(d,[["render",p]]);export{f as __pageData,_ as default};
